    test("human - bam - GC - folder inputs") {
        when {
            params {
                module_args = [
                    gender    :  'XY',
                    genomeVersion : 'hg19',
                    minCounts :  '1',
                    min_base_qual : '1',
                    min_map_qual  : '1',
                    chrom_names  : 'c("21")',
                    penalty: '70'
                ]
                allele_folder = "G1000_alleles_hg38"
                loci_folder   = "G1000_loci_hg38"
                gc_folder   = "GC_G1000_hg38_21"
                rt_folder   = "RT_G1000_hg38_21"
            }
            process {
                """

                file(params.allele_folder).mkdirs()
                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/ascat/G1000_alleles_hg38_chr21.txt', checkIfExists: true)
                    .copyTo(params.allele_folder + '/G1000_alleles_hg38_chr21.txt')
                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/ascat/G1000_alleles_hg38_chr22.txt', checkIfExists: true)
                    .copyTo(params.allele_folder + '/G1000_alleles_hg38_chr22.txt')

                file(params.loci_folder).mkdirs()
                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/ascat/G1000_loci_hg38_chr21.txt', checkIfExists: true)
                    .copyTo(params.loci_folder + '/G1000_loci_hg38_chr21.txt')
                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/ascat/G1000_loci_hg38_chr22.txt', checkIfExists: true)
