                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/ascat/RT_G1000_hg38_21.txt', checkIfExists: true)
                    .copyTo(params.rt_folder + '/RT_G1000_hg38_21.txt')

                input[0] = [
